package com.smartseating.ui;

import com.smartseating.dao.SemesterDAO;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;

public class SemesterFrame extends AppFrame {
    private final SemesterDAO dao=new SemesterDAO();private final JComboBox<String> number=new JComboBox<>(new String[]{"S1","S2","S3","S4","S5","S6","S7","S8"});private final JTextField year=new JTextField("2025-26");private final JComboBox<String> status=new JComboBox<>(new String[]{"ACTIVE","INACTIVE"});private final JTable table=new JTable();private Semester selected;
    public SemesterFrame(User user){super("Semester Management",user);UI.frame(this,870,590);build();refresh();}
    private void build(){content.add(title("Semester Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Semester Number",number);UI.addField(form,1,"Academic Year",year);UI.addField(form,2,"Status",status);JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton add=button("ADD",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=3;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Semester List",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});if("TEACHER".equals(currentUser.getRole())){add.setEnabled(false);update.setEnabled(false);del.setEnabled(false);}}
    private Semester read(){return new Semester(0,(String)number.getSelectedItem(),Validation.text(year.getText(),"Academic year"),(String)status.getSelectedItem());}private void save(){try{dao.save(read());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a semester first.");Semester s=read();s.setId(selected.getId());dao.update(s);clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a semester first.");if(confirm("Delete selected semester?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){int r=table.getSelectedRow();selected=new Semester((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),String.valueOf(table.getValueAt(r,3)));number.setSelectedItem(selected.getNumber());year.setText(selected.getAcademicYear());status.setSelectedItem(selected.getStatus());}private void clear(){selected=null;year.setText("2025-26");table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Semester","Academic Year","Status"},0);for(Semester s:dao.findAll())m.addRow(new Object[]{s.getId(),s.getNumber(),s.getAcademicYear(),s.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("SEMESTER LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append("\n");return b.toString();}
}
